/**
 * @fileoverview A package the `ext.b` module imports to load files (#717): it imports the URL it is given.
 * @module api_tests/api_test_host_record_leaf/node_modules/load-pkg
 */

/**
 * Import a module.
 * @param {URL|string} url - The module's URL.
 * @returns {Promise<object>} Its namespace.
 * @example
 * await load(new URL("./x.mjs", import.meta.url));
 */
export function load(url) {
	return import(url);
}
